-- ----------------------------
-- Table structure for dev_base_device
-- ----------------------------
DROP TABLE IF EXISTS `dev_base_device`;
CREATE TABLE `dev_base_device`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '系统编号',
  `device_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设备名称',
  `device_no` int(11) NULL DEFAULT NULL COMMENT '设备唯一标识',
  `device_id` int(4) NULL DEFAULT NULL COMMENT '设备通讯编号 即设备ID ',
  `region_id` bigint(20) NULL DEFAULT NULL COMMENT '设备所在区域',
  `online_status` int(2) NULL DEFAULT 0 COMMENT '通信状态（0离红; 1在线）由设备自行检测',
  `device_status` int(2) NULL DEFAULT 0 COMMENT '设备状态（1故障/告警; 0正常）由设备自行检测',
  `run_status` int(2) NULL DEFAULT 0 COMMENT '运行开关（0关; 1开）设备系统开关',
  `run_mode` int(2) NULL DEFAULT 0 COMMENT '运行模式（0自动; 1手动）运行模式',
  `run_mode_type` int(2) NULL DEFAULT 0 COMMENT '运行模式类型1，普通时控；2，场景时控；3，红外传感；4，照度传感；',
  `temperature` decimal(10, 1) NULL DEFAULT NULL COMMENT '环境温度',
  `ac_input_loop` int(2) NULL DEFAULT NULL COMMENT '交流输入路数',
  `ac_current_display` int(2) NULL DEFAULT NULL COMMENT '交流电流显示',
  `ac_sampling_mode` int(2) NULL DEFAULT NULL COMMENT '交流采样模式',
  `dc_module_num` int(11) NULL DEFAULT 0 COMMENT '直流模块个数',
  `ac_loop_num` int(11) NULL DEFAULT NULL COMMENT '交流回路数量',
  `other_switch_num` int(11) NULL DEFAULT NULL COMMENT '其他开关数量',
  `ac_module_num` int(11) NULL DEFAULT NULL COMMENT '交流模块回路数',
  `dimmer_num` int(11) NULL DEFAULT 0 COMMENT '调光回路数',
  `dc_switch_num` int(11) NULL DEFAULT NULL COMMENT '直流开关回路数',
  `dc_bus_voltage` decimal(10, 1) NULL DEFAULT NULL COMMENT '直流母线电压',
  `dc_bus_current` decimal(10, 1) NULL DEFAULT NULL COMMENT '直流母线电流',
  `bus_direct_voltage_to_earth` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线正对地电压',
  `bus_negative_voltage_to_earth` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线负对地电压',
  `positive_pole_resistance` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线正极绝缘阻值',
  `negative_pole_resistance` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线负极绝缘阻值',
  `busbar_crossover_voltage` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线交窜直电压',
  `busbar_crossover_current` decimal(10, 1) NULL DEFAULT NULL COMMENT '母线交窜直电流(没有该协议，此处写错)',
  `last_time` datetime NULL DEFAULT NULL COMMENT '最后一次心跳时间',
  `version` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '主监控版本',
  `ip` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `port` int(11) NULL DEFAULT NULL COMMENT '端口号',
  `type` int(2) NULL DEFAULT NULL COMMENT '机柜类型 （1:电源柜 0:配电柜）',
  `ac_dc_output_voltage` int(5) NULL DEFAULT NULL COMMENT 'AC/DC输出电压，为null时表示未设置',
  `dc_dc_output_voltage` int(5) NULL DEFAULT NULL COMMENT 'DC/DC输出电压，为null时表示未设置',
  `scene_select` int(4) NULL DEFAULT NULL COMMENT '当前机柜所在场景',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '机柜 业务实现类不要直接用代码生成替换！！！！！！！！！！！！！！！！！！！！' ROW_FORMAT = DYNAMIC;

