  `id` int(5) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `device_no` int(5) NULL DEFAULT NULL COMMENT '设备通讯编号',
  `year` int(5) NULL DEFAULT NULL COMMENT '年',
  `month` int(5) NULL DEFAULT NULL COMMENT '月',
  `day` int(5) NULL DEFAULT NULL COMMENT '日',
  `hour` int(5) NULL DEFAULT NULL COMMENT '时',
  `minute` int(5) NULL DEFAULT NULL COMMENT '分',
  `second` int(5) NULL DEFAULT NULL COMMENT '秒',
  `time_switch` int(2) NULL DEFAULT NULL COMMENT '对时标志位 0不启用 1启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '机柜时间设置表' ROW_FORMAT = DYNAMIC;

