  `loop_two_overvoltage` int(11) NULL DEFAULT NULL COMMENT 'PM6US交流二路过压',
  `loop_two_defaultphase` int(11) NULL DEFAULT NULL COMMENT 'PM6US交流二路缺相',
  `bus_positive_insulation` int(11) NULL DEFAULT NULL COMMENT '母线正极绝缘故障',
  `bus_negative_insulation` int(11) NULL DEFAULT NULL COMMENT '母线负极绝缘故障',
  `branch_positive_insulation` int(11) NULL DEFAULT NULL COMMENT '支路正极绝缘故障',
  `branch_negative_insulation` int(11) NULL DEFAULT NULL COMMENT '支路负极绝缘故障',
  `bus_differential_pressure` int(11) NULL DEFAULT NULL COMMENT '母线差压故障',
  `branch_switch_fault` int(11) NULL DEFAULT NULL COMMENT '支路开关总故障',
  `bus_positive_acdc_fault` int(11) NULL DEFAULT NULL COMMENT '母线正极交窜直故障',
  `bus_negative_acdc_fault` int(11) NULL DEFAULT NULL COMMENT '母线负极交窜直故障 ',
  `branch_acdc_fault` int(11) NULL DEFAULT NULL COMMENT '支路交窜直故障',
  `bus_overvoltage` int(11) NULL DEFAULT NULL COMMENT '母线过压故障',
  `bus_undervoltage` int(11) NULL DEFAULT NULL COMMENT '母线欠压故障',
  `system_fault` int(11) NULL DEFAULT NULL COMMENT '系统总故障',
  `system_switch` int(11) NULL DEFAULT NULL COMMENT '系统总开关状态 1：开启 0：关闭',
  `system_module` int(11) NULL DEFAULT NULL COMMENT '系统工作模式 1：手动 0：自动',
  `btc` int(11) NULL DEFAULT NULL COMMENT 'BTC单元有无',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'PM6U故障记录表' ROW_FORMAT = DYNAMIC;

