DROP TABLE IF EXISTS `dev_status_ac`;
CREATE TABLE `dev_status_ac`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '系统编号',
  `device_id` bigint(20) NULL DEFAULT NULL COMMENT '设备id',
  `circuit_num` bigint(11) NULL DEFAULT NULL COMMENT '电路数：1路；2路',
  `uab` decimal(11, 1) NULL DEFAULT NULL COMMENT 'AB线电压',
  `ubc` decimal(11, 1) NULL DEFAULT NULL COMMENT 'BC线电压',
  `uac` decimal(11, 1) NULL DEFAULT NULL COMMENT 'CA线电压',
  `ia` decimal(11, 1) NULL DEFAULT NULL COMMENT 'A相电流',
  `ib` decimal(11, 1) NULL DEFAULT NULL COMMENT 'B相电流',
  `ic` decimal(11, 1) NULL DEFAULT NULL COMMENT 'C相电流',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '交流信息' ROW_FORMAT = DYNAMIC;

