  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '系统编号',
  `device_id` bigint(20) NULL DEFAULT NULL COMMENT '设备id',
  `no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '回路编号，从协议读取',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '分组编号,与config_group编号对应',
  `brightness_setting` int(11) NULL DEFAULT NULL COMMENT '亮度设定值',
  `brightness_feedback` int(11) NULL DEFAULT NULL COMMENT '亮度反馈值',
  `output_voltage` decimal(10, 1) NULL DEFAULT NULL COMMENT '输出电压',
  `output_current` decimal(10, 1) NULL DEFAULT NULL COMMENT '输出电流',
  `internal_temperature` decimal(5, 1) NULL DEFAULT NULL COMMENT '内部温度（摄氏度）',
  `switch_setting` int(3) NULL DEFAULT NULL COMMENT '开关设定(0 关闭 1打开)',
  `switch_feedback` int(3) NULL DEFAULT NULL COMMENT '开关反馈(0 关闭 1打开)',
  `real_time` decimal(10, 1) NULL DEFAULT NULL COMMENT '实时功率',
  `select_status` int(2) NULL DEFAULT NULL COMMENT '调光控制列表的选中状态 0不选中 1选中  null 未选中',
