  `addr` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '协议地址',
  `addr_num` int(11) NULL DEFAULT NULL COMMENT '操作的地址数量',
  `write_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '写入地址的值',
  `type` int(11) NULL DEFAULT NULL COMMENT '类型 1：发送指令 2：接收指令 4：机柜初始化指令',
  `feedback` int(11) NULL DEFAULT NULL COMMENT '反馈 0：正常 1：异常 2：在等待队列中',
  `timestamp` bigint(20) NULL DEFAULT NULL COMMENT '时间戳',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '写入协议的指令下发表' ROW_FORMAT = DYNAMIC;

